style.css:
@-moz-document domain("youtube.com") {
/* ? Cinnamoroll YouTube Theme ? */
/* Made for Stylish by Leni! */

/* Background */
html, body {
  background: linear-gradient(to bottom, #bde9f7, #ffd9ec) !important;
  font-family: sans-serif !important;
}

/* Top bar */
#masthead {
  background: #ffffff !important;
  border-bottom: 3px solid #a8e4f0 !important;
}

/* Sidebar menu */
#guide-content {
  background: rgba(255, 255, 255, 0.7) !important;
  border-radius: 15px !important;
  padding: 10px !important;
}

/* Video titles */
#video-title {
  color: #6a90a9 !important;
  font-weight: 600 !important;
}

/* Thumbnails */
ytd-thumbnail {
  border-radius: 20px !important;
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.6);
}

/* Buttons (Subscribe, Like, etc.) */
ytd-button-renderer, ytd-toggle-button-renderer {
  background-color: #ffd9ec !important;
  color: #6a90a9 !important;
  border-radius: 25px !important;
  padding: 5px 10px !important;
}

/* Comments section */
#comments {
  background: rgba(255, 255, 255, 0.6) !important;
  border-radius: 20px !important;
  padding: 10px !important;
}

/* Optional: cute background image */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url("https://i.imgur.com/J6B8Cpj.png") center/contain no-repeat;
  opacity: 0.2;
  z-index: -1;
}
}
